class Produto:
    total_cadastrados = 0
    ESTOQUE_MINIMO = 5

    def __init__(self, nome, preco, quantidade=0):
        if preco <= 0:
            raise ValueError(f"Preço inválido para {nome}.")
        if quantidade < 0:
            raise ValueError(f"Quantidade inválida para {nome}.")
        self.nome = nome
        self.preco = preco
        self.quantidade = quantidade
        Produto.total_cadastrados += 1

    def entrada(self, qtd):
        self.quantidade += qtd

    def saida(self, qtd):
        if qtd > self.quantidade:
            print(f"Estoque insuficiente de {self.nome}: há {self.quantidade}.")
            return
        self.quantidade -= qtd

    def valor_em_estoque(self):
        return self.preco * self.quantidade

    def precisa_repor(self):
        return self.quantidade < Produto.ESTOQUE_MINIMO

    def resumo(self):
        alerta = " (repor!)" if self.precisa_repor() else ""
        return f"{self.nome}: {self.quantidade} un. x R$ {self.preco:.2f} = R$ {self.valor_em_estoque():.2f}{alerta}"


estoque = [
    Produto("Caneta", 2.50, 40),
    Produto("Caderno", 18.90, 12),
    Produto("Mochila", 120.00, 3),
]

estoque[0].saida(15)
estoque[1].saida(20)
estoque[2].entrada(1)

total = 0
for produto in estoque:
    print(produto.resumo())
    total += produto.valor_em_estoque()

print(f"Produtos cadastrados: {Produto.total_cadastrados}")
print(f"Valor total do estoque: R$ {total:.2f}")

