        self.ligada = False

    def alternar(self):
        self.ligada = not self.ligada

    def estado(self):
        return "acesa" if self.ligada else "apagada"

lampada = Lampada()
lampada.alternar()
print(lampada.estado())  # acesa
lampada.alternar()
