class Circulo:
    PI = 3.14159

    def __init__(self, raio):
        self.raio = raio

    def area(self):
        return Circulo.PI * self.raio ** 2

    def perimetro(self):
        return 2 * Circulo.PI * self.raio

c = Circulo(3)
print(f"Área: {c.area():.2f}, perímetro: {c.perimetro():.2f}")  # 28.27 e 18.85

class Termometro:
    def __init__(self, celsius):
        self.celsius = celsius

    def para_fahrenheit(self):
        return self.celsius * 9 / 5 + 32

    def classificar(self):
        if self.celsius >= 30:
            return "quente"
        elif self.celsius >= 20:
            return "agradável"
        return "frio"

for t in [Termometro(15), Termometro(25), Termometro(32)]:
    print(f"{t.celsius}°C = {t.para_fahrenheit():.1f}°F ({t.classificar()})")

class Aluno:
    def __init__(self, nome):
        self.nome = nome
        self.notas = []

    def adicionar_nota(self, nota):
        if nota < 0 or nota > 10:
            print("Nota inválida:", nota)
            return
        self.notas.append(nota)

    def media(self):
        if len(self.notas) == 0:
            return 0
        return sum(self.notas) / len(self.notas)

    def situacao(self):
        return "Aprovado" if self.media() >= 7 else "Recuperação"

aluno = Aluno("Lia")
for n in [8, 6.5, 9, 11]:
    aluno.adicionar_nota(n)
print(f"{aluno.nome}: média {aluno.media():.2f} - {aluno.situacao()}")
# Nota inválida: 11
# Lia: média 7.83 - Aprovado

class Cofrinho:
    def __init__(self, meta):
        if meta <= 0:
            raise ValueError("A meta deve ser maior que zero.")
        self.meta = meta
        self.saldo = 0

    def guardar(self, valor):
        if valor <= 0:
            print("Valor inválido.")
            return
        self.saldo += valor

    def progresso(self):
        return min(self.saldo / self.meta * 100, 100)

    def atingiu(self):
        return self.saldo >= self.meta

cofre = Cofrinho(500)
for v in [100, 150, -20, 300]:
    cofre.guardar(v)
print(f"Progresso: {cofre.progresso():.0f}% | Meta atingida? {cofre.atingiu()}")

